create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if not coalesce(v,false) then raise exception 'VIEWS/TEMPLATES: %',label;end if;end$$;
create function pg_temp.reject(q text,code text,msg text default null) returns boolean language plpgsql as $$begin execute q;return false;exception when others then if sqlstate<>code or msg is not null and strpos(sqlerrm,msg)=0 then raise exception 'Unexpected SQLSTATE % expected % (%): %',sqlstate,code,msg,sqlerrm;end if;return true;end$$;
create function pg_temp.hidden(q text) returns boolean language plpgsql as $$declare n bigint;begin execute q;get diagnostics n=row_count;return n=0;exception when insufficient_privilege then return true;end$$;
create temp table ctx(k text primary key,id uuid);grant all on ctx to authenticated;
