select set_config('request.jwt.claims','{"role":"authenticated","email":"views.admin@synthetic.test"}',true);
select public.custom_field_save_definition((select id from ctx where k='field'),'people','Synthetic grouping field','single_select',0,true,true,3);
select pg_temp.ok((public.customization_view_data((select id from ctx where k='view'),(select id from ctx where k='option-b'))->>'warning')::boolean,'archived field degrades even bucket URLs');
select pg_temp.ok(public.customization_view_data((select id from ctx where k='view'))::text not like '%Synthetic grouping field%','archived field name omitted');
select pg_temp.ok(public.customization_view_data((select id from ctx where k='view'))->'spec'->>'mode'='table','archived grouping falls back to table');
select pg_temp.ok(pg_temp.reject($q$select public.save_customization_view(null,'people','Synthetic archived field',false,(select filters from public.saved_views where id=(select id from ctx where k='view')))$q$,'22023','Field unavailable'),'new spec cannot reference archived field');
reset role;
-- DELETE: disposable card fixture, proving history adds no FK-based hidden-reference side channel.
delete from public.crm_board_items where id='f8000000-0000-0000-0000-000000000032';
select pg_temp.ok(exists(select 1 from public.crm_template_applications where card_id='f8000000-0000-0000-0000-000000000032'),'card removal preserves protected reference history');
reset role;
insert into public.tasks(company_id,deal_id,title) values('f8000000-0000-0000-0000-000000000001','f8000000-0000-0000-0000-000000000021','Synthetic archived Deal audited task'),('f8000000-0000-0000-0000-000000000002',null,'Synthetic deleted Company audited task');
create temp table expected_task_audit as select id from public.audit_log where entity_table='tasks' and (after_row->>'title' in('Synthetic archived Deal audited task','Synthetic deleted Company audited task'));grant select on expected_task_audit to authenticated;
select pg_temp.ok((select count(*)=2 from expected_task_audit),'nonempty archived/deleted task audit fixture');
update private.customization_configuration set views_enabled=false,kanban_enabled=false,templates_enabled=false;
set local role authenticated;
select pg_temp.ok(public.customization_state()='{"views":false,"kanban":false,"templates":false}','same session sees pause');
select pg_temp.ok((select count(*)=2 from public.audit_log a join expected_task_audit e using(id)),'flags-off admin retains archived Deal and deleted Company task audit');
select pg_temp.ok(not exists(select 1 from private.vt_application_commands),'command envelopes never persist after a successful application');

select pg_temp.ok(pg_temp.reject($q$select public.customization_view_data((select id from ctx where k='view'))$q$,'42501','Customization unavailable'),'paused reads denied');
select pg_temp.ok(pg_temp.reject($q$select public.apply_task_template((select id from ctx where k='template'),1,'f8000000-0000-0000-0000-000000000001',null,null,gen_random_uuid(),false,true)$q$,'42501','paused'),'paused application denied');
select set_config('request.jwt.claims','{"role":"authenticated","email":"views.one@synthetic.test"}',true);
select pg_temp.ok((select filters='{"view":"all","q":"Synthetic v0","cols":["email"]}' from public.saved_views where name='Synthetic v0'),'v0 row stays byte-semantically intact');
select pg_temp.ok(pg_temp.reject($q$delete from public.saved_views where id=(select id from ctx where k='view')$q$,'42501','paused'),'loaded v1 delete cannot bypass pause through legacy action');
insert into public.saved_views(object_type,name,owner,filters) values('people','Synthetic paused v0','views.one@synthetic.test','{}');
-- DELETE: disposable v0 fixture only, proving legacy deletion stays available while 6B is paused.
delete from public.saved_views where name='Synthetic paused v0';
select pg_temp.ok(not exists(select 1 from public.saved_views where name='Synthetic paused v0'),'v0 CRUD remains available while 6B off');
reset role;
insert into auth.users(id,email) values('f8000000-0000-0000-0000-000000000090','views.machine@synthetic.test');
insert into private.machine_identities(sub,enabled,relationships_only) values('f8000000-0000-0000-0000-000000000090',true,true);
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"f8000000-0000-0000-0000-000000000090","email":"views.machine@synthetic.test"}',true);
select pg_temp.ok(pg_temp.reject('select public.customization_state()','42501'),'machine denied');
select pg_temp.ok(pg_temp.hidden('select * from public.crm_task_templates'),'machine template table denied');
select pg_temp.ok(pg_temp.hidden('select * from public.crm_template_applications'),'machine application table denied');
select pg_temp.ok(pg_temp.hidden('select * from public.crm_template_audit_metadata'),'machine journal denied');
select pg_temp.ok(pg_temp.hidden('select * from private.vt_application_commands'),'machine command denied');
reset role;
select pg_temp.ok((select count(*)=5 from pg_policy where polname='machine_identity_isolation' and polrelid in('private.customization_configuration'::regclass,'private.vt_application_commands'::regclass,'public.crm_task_templates'::regclass,'public.crm_template_applications'::regclass,'public.crm_template_audit_metadata'::regclass) and pg_get_expr(polqual,polrelid) like '%SELECT%' and pg_get_expr(polwithcheck,polrelid) like '%SELECT%'),'five new tables have initplan machine isolation');
select pg_temp.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('customization_state','save_customization_view','customization_view_data','move_customization_card','save_task_template','apply_task_template') and p.prosecdef),'all new public functions invoker');
rollback;
